descFull: {
  bn: "ঠিক তেমনই সংস্কৃতির পুনরুজ্জীবন কালচক্রের অনুরূপ, যেখানে জীবন হলো শূন্য মুহূর্তের প্রতিচ্ছবি এবং ০-৯ সংখ্যাগুলোর মধ্যে জীবনের প্রত্যাবর্তন; চিত্রের কেন্দ্রীয় বিন্দু, সমকেন্দ্রিক বৃত্ত এবং জ্যামিতিক স্তরবিন্যাস অসংখ্য পর্যায়ের পারস্পরিক সংযোগ নির্দেশ করে; প্রতিটি চক্র পূর্বের অভিজ্ঞতাকে ধারণ করে নতুন বিন্যাসের সম্ভাবনা সৃষ্টি করে, ফলে সময় কেবল অতীত থেকে ভবিষ্যতের সরল গতি নয়, বরং পুনরাবর্তন ও রূপান্তরের ধারা; সহস্রাব্দের বিস্তৃত পরিসরে জীবন ও বিশ্বজগতের পরিবর্তন একই ছন্দে যুক্ত হয়; চিত্রটি মহাজাগতিক পুনর্গঠনকে অস্তিত্বের অবিরাম প্রবাহের প্রতিরূপ হিসেবে প্রকাশ করে;",

  en: "the cycle of rain, the renewal of culture follows the rhythm of the cosmic cycle, where life is reflected in the zero moment and its return is symbolically expressed through the numbers 0–9; the central point, concentric circles and geometric layers in the painting reveal the interconnectedness of countless stages; each cycle carries the experience of the past while creating possibilities for a new arrangement; time is therefore not merely a linear movement from past to future, but a continuous process of recurrence and transformation; across the vast expanse of millennia, the changes of life and the universe become connected through a shared rhythm; the painting presents cosmic reconstruction as a reflection of the ceaseless flow of existence;",

  hi: "है, उसी प्रकार संस्कृति का पुनरुज्जीवन कालचक्र की लय का अनुसरण करता है, जहाँ जीवन शून्य क्षण में प्रतिबिंबित होता है और ०–९ की संख्याओं के माध्यम से जीवन की पुनरावृत्ति व्यक्त होती है; चित्र का केंद्रीय बिंदु, समकेंद्रित वृत्त और ज्यामितीय स्तरों का विन्यास असंख्य चरणों के पारस्परिक संबंध को दर्शाता है; प्रत्येक चक्र पूर्व अनुभवों को समाहित करके नए विन्यास की संभावनाएँ उत्पन्न करता है; अतः समय केवल अतीत से भविष्य की सीधी गति नहीं, बल्कि पुनरावर्तन और रूपांतरण की निरंतर धारा है; सहस्राब्दियों के विस्तृत विस्तार में जीवन और ब्रह्मांड के परिवर्तन एक ही लय में जुड़ जाते हैं; यह चित्र ब्रह्मांडीय पुनर्गठन को अस्तित्व के अविराम प्रवाह के प्रतिरूप के रूप में प्रस्तुत करता है;",

  sa: "भवति, तथैव संस्कृतेः पुनरुज्जीवनं कालचक्रस्य लयम् अनुसरति, यत्र जीवनं शून्यक्षणे प्रतिबिम्बितं भवति तथा ०–९ सङ्ख्यानां माध्यमेन जीवनस्य पुनरावर्तनं प्रतीकात्मकरूपेण व्यक्तं भवति; चित्रस्य केन्द्रबिन्दुः, समकेन्द्रिकवृत्तानि, ज्यामितीयस्तराणां विन्यासश्च असङ्ख्यानां चरणानां पारस्परिकसम्बन्धं सूचयन्ति; प्रत्येकं चक्रं पूर्वानुभवान् धारयित्वा नूतनविन्यासस्य सम्भावनाः जनयति; अतः कालः केवलम् अतीतात् भविष्यं प्रति सरलः प्रवाहः न, अपि तु पुनरावर्तनस्य रूपान्तरणस्य च निरन्तरा धारा; सहस्राब्दानां विस्तृतकाले जीवनस्य विश्वब्रह्माण्डस्य च परिवर्तनानि एकेनैव लयेन सम्बध्यन्ते; इदं चित्रं ब्रह्माण्डीयपुनर्निर्माणम् अस्तित्वस्य अविरामप्रवाहस्य प्रतिरूपत्वेन प्रकाशयति;"
},
 
