  sa: "आत्मनः समर्पणस्य आध्यात्मिकं तात्पर्यं प्रकाशयति; अत्र ‘शून्यवर्षम्’ इति प्रतीकात्मककल्पना कालस्य नूतनारम्भं तथा ख्रीष्टाब्दात् आरब्धायाः सहस्राब्द्याः परिवर्तनशीलां गतिं स्मारयति, यत्र शून्यस्य वास्तविकम् अर्थः काले मार्गदर्शकतत्त्वत्वेन प्रकटते; चित्रस्य केन्द्रीयं मुखमण्डलं, वृत्ताकारविन्यासे प्रतिबिम्बितानि अक्षराणि सङ्ख्याश्च शून्यक्षणस्य माध्यमेन नवजन्मनः पुनर्जागरणस्य च चक्रं प्रकाशयन्ति तथा शून्यता, जीवनं, विश्वासः, आशा च एकीकृतानुभूतिरूपेण प्रस्तुतयन्ति;"
