descFull: {
  bn: "পথপ্রদর্শক হয়ে ওঠে, এবং ধ্যানের গভীর পর্যায়ে এই ধ্বনি আত্ম-আবিষ্কার, আত্মসংযম ও অন্তরের শান্তির প্রতীক হয়ে দাঁড়ায়; প্রাকৃতিক জীবন সৃষ্টির ঊষালগ্নে পিতামাতার অস্তিত্বের সংযোগ বিনোদনমূলক জীবনকে প্রভাবিত করে, যা প্রাকৃতিক জীবনেরই একটি প্রতিচ্ছবি; তাই দৃশ্যমান রূপের আড়ালে নীরব স্পন্দন জীবনের সূক্ষ্ম উপলব্ধিকে প্রকাশ করে, যেখানে শ্বাস, মনোযোগ ও চেতনা একই ছন্দে মিলিত হয়; এই মিলন দেহ-মনের অস্থিরতা অতিক্রম করে সত্যের সন্ধানে অন্তর্মুখী যাত্রার সূচনা করে; চিত্রটি ধ্যানমগ্ন জীবনের শুদ্ধি, ভারসাম্য ও আত্মজাগরণের এক প্রতীকী প্রকাশ;",

  en: "awakening, the chanting of Om becomes a guiding force, while in the deeper stages of meditation, this sound symbolizes self-discovery, self-restraint, and inner peace; at the dawn of the creation of natural life, the connection between parental existence influences the life of recreation, reflecting an aspect of natural existence; thus, beneath visible forms, a silent vibration reveals the subtle awareness of life, where breath, concentration, and consciousness merge into a shared rhythm; this harmony transcends the restlessness of body and mind and initiates an inward journey in search of truth; the painting symbolically expresses the purification, balance, and self-awakening of a meditative life;",

  hi: "जबकि ध्यान की गहन अवस्था में यही ध्वनि आत्म-अन्वेषण, आत्मसंयम और आंतरिक शांति का प्रतीक बन जाती है; प्राकृतिक जीवन की सृष्टि के उषाकाल में माता-पिता के अस्तित्व का संबंध मनोरंजनमय जीवन को प्रभावित करता है, जो प्राकृतिक जीवन का ही एक प्रतिबिंब है; इस प्रकार दृश्य रूपों के पीछे छिपा मौन स्पंदन जीवन की सूक्ष्म अनुभूति को प्रकट करता है, जहाँ श्वास, एकाग्रता और चेतना एक ही लय में मिल जाते हैं; यह समन्वय देह-मन की अस्थिरता से ऊपर उठकर सत्य की खोज में अंतर्मुखी यात्रा का आरंभ करता है; यह चित्र ध्यानमय जीवन की शुद्धि, संतुलन और आत्मजागरण की प्रतीकात्मक अभिव्यक्ति है;",

  sa: "ध्यानस्य गभीरेषु स्तरेषु च एषा ध्वनिः आत्मान्वेषणस्य, आत्मसंयमस्य, अन्तःशान्तेश्च प्रतीकरूपेण तिष्ठति; प्राकृतिकजीवनस्य सृष्टेः उषःकाले मातापित्रोः अस्तित्वस्य सम्बन्धः विनोदमयजीवनं प्रभावितं करोति, यत् प्राकृतिकजीवनस्यैव प्रतिबिम्बम् अस्ति; अतः दृश्यरूपाणाम् अन्तः स्थितः मौनस्पन्दः जीवनस्य सूक्ष्माम् अनुभूतिं प्रकाशयति, यत्र श्वासः, एकाग्रता, चेतना च एकस्मिन् लये मिलन्ति; एषः समन्वयः देह-मनसोः अस्थिरताम् अतिक्रम्य सत्यस्य अन्वेषणे अन्तर्मुखयात्रायाः आरम्भं करोति; चित्रम् ध्यानमयजीवनस्य शुद्धेः, सन्तुलनस्य, आत्मजागरणस्य च प्रतीकात्मकं प्रकटीकरणम् अस्ति;",
},

