descFull: {
  bn: "প্রকৃতির উপস্থাপনায় জীবনের প্রতিটি রূপ জন্ম থেকেই শাশ্বত ও পূর্ণাঙ্গ, যেখানে বাস্তবতার সঙ্গে জীবনচক্রের আত্ম-উপলব্ধি পরিলক্ষিত হয়, যা জাগতিক ও আধ্যাত্মিক জীবনকে সংযুক্ত করে; তাই তপস্যার নীরবতা এখানে কেবল সাধনার প্রতীক নয়, বরং অন্তর্দৃষ্টির মাধ্যমে সত্য উপলব্ধির এক পথ—সীতা ও রামের যুগল উপস্থিতি স্ব-প্রেম, স্ব-দায়িত্ব ও পারস্পরিক আস্থার সাংস্কৃতিক আদর্শ তুলে ধরে; প্রকৃতির শান্ত পরিবেশে এই আধ্যাত্মিক সংযোগ জীবন-সংস্কৃতির ধারাবাহিকতাকে সমৃদ্ধ করে; চিত্রটি ত্যাগ, ধৈর্য ও আত্মনিবেদনের মধ্য দিয়ে জীবনের গভীর ঐক্য প্রকাশ করে;",

  en: "and nature; every expression of life, as presented through nature, is eternal and complete from its origin, revealing the self-realization of the life cycle in relation to reality and connecting worldly existence with spiritual life; thus, the silence of meditation is not merely a symbol of spiritual practice, but a path towards truth through inner insight; the presence of Sita and Rama together expresses the cultural ideals of self-love, self-responsibility, and mutual trust; within nature’s tranquil surroundings, this spiritual connection enriches the continuity of life-culture; the painting reveals life’s deeper unity through renunciation, patience, and self-dedication;",

  hi: "अभिव्यक्ति में जीवन का प्रत्येक रूप अपने उद्गम से ही शाश्वत और पूर्ण है, जहाँ वास्तविकता के साथ जीवनचक्र की आत्मानुभूति परिलक्षित होती है और लौकिक तथा आध्यात्मिक जीवन एक-दूसरे से जुड़ते हैं; इसलिए तपस्या का मौन यहाँ केवल साधना का प्रतीक नहीं, बल्कि अंतर्दृष्टि के माध्यम से सत्य की अनुभूति का मार्ग है; सीता और राम की संयुक्त उपस्थिति आत्मप्रेम, आत्मदायित्व और पारस्परिक विश्वास के सांस्कृतिक आदर्श प्रस्तुत करती है; प्रकृति के शांत वातावरण में यह आध्यात्मिक संबंध जीवन-संस्कृति की निरंतरता को समृद्ध करता है; यह चित्र त्याग, धैर्य और आत्मसमर्पण के माध्यम से जीवन की गहरी एकता व्यक्त करता है;",

  sa: "जन्मनः प्रभृति शाश्वतं पूर्णं च भवति, यत्र वास्तविकतया सह जीवनचक्रस्य आत्मानुभूतिः दृश्यते तथा लौकिकं आध्यात्मिकं जीवनं च परस्परं संयुज्यते; अतः तपसः मौनम् अत्र केवलं साधनायाः प्रतीकं न, अपितु अन्तर्दृष्ट्या सत्यस्य अनुभूतेः मार्गः; सीतारामयोः युगलोपस्थितिः आत्मप्रेम्णः, स्वदायित्वस्य, पारस्परिकविश्वासस्य च सांस्कृतिकान् आदर्शान् प्रकाशयति; प्रकृतेः शान्ते वातावरणे एषः आध्यात्मिकसम्बन्धः जीवनसंस्कृतेः सातत्यं समृद्धयति; चित्रं त्यागेन, धैर्येण, आत्मसमर्पणेन च जीवनस्य गभीराम् एकतां प्रकाशयति;"
},

