  sa: "तरङ्गाः जागरन्ति — शरीरमनसोः सङ्गमेन संयमेन च अस्तित्वं समृद्धयन्ति; एतत् दीप्तिमतीं चेतनां प्रतिबिम्बयति, पूर्णसूर्यग्रहणमिव यत् सूक्ष्मरूपेण जगत् रूपान्तरीकरोति;",
